#include <iostream>
#include <algorithm>
using namespace std;

struct Activity {
    int start, end;
};

int main() {
    int n;
    cin >> n;
    Activity a[1000];
    for (int i = 0; i < n; i++) cin >> a[i].start >> a[i].end;
    sort(a, a + n, [](const Activity& x, const Activity& y) {
        return x.end < y.end;
    });
    int cnt = 1, lastEnd = a[0].end;
    for (int i = 1; i < n; i++) {
        if (a[i].start >= lastEnd) {
            cnt++;
            lastEnd = a[i].end;
        }
    }
    cout << cnt << endl;
    return 0;
}

#include <iostream>
#include <algorithm>
#include <string>
using namespace std;

bool cmp(const string& a, const string& b) {
    return a + b < b + a;
}

int main() {
    int n;
    cin >> n;
    string nums[1000];
    for (int i = 0; i < n; i++) cin >> nums[i];
    sort(nums, nums + n, cmp);
    string result;
    for (int i = 0; i < n; i++) result += nums[i];
    cout << result << endl;
    return 0;
}

#include <iostream>
#include <algorithm>
#include <queue>
using namespace std;

int main() {
    int n;
    cin >> n;
    pair<int,int> intervals[1000];
    for (int i = 0; i < n; i++) cin >> intervals[i].first >> intervals[i].second;
    sort(intervals, intervals + n);
    priority_queue<int, vector<int>, greater<int>> rooms;
    for (int i = 0; i < n; i++) {
        if (!rooms.empty() && rooms.top() <= intervals[i].first) {
            rooms.pop();
        }
        rooms.push(intervals[i].second);
    }
    cout << rooms.size() << endl;
    return 0;
}

#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int n, limit;
    cin >> n >> limit;
    int w[100000];
    for (int i = 0; i < n; i++) cin >> w[i];
    sort(w, w + n);
    int boats = 0, left = 0, right = n - 1;
    while (left <= right) {
        if (w[left] + w[right] <= limit) {
            left++;
        }
        right--;
        boats++;
    }
    cout << boats << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string s;
    int k;
    cin >> s >> k;
    string result;
    for (char c : s) {
        while (!result.empty() && k > 0 && result.back() > c) {
            result.pop_back();
            k--;
        }
        result.push_back(c);
    }
    while (k > 0) {
        result.pop_back();
        k--;
    }
    cout << result << endl;
    return 0;
}

